use vstd::prelude::*;

// A simple enum to tag a vector as a row or a column.
pub enum ExpandedVector<T> {
    RowVector(Vec<T>),
    ColumnVector(Vec<T>),
}

impl<T> ExpandedVector<T> {
    // Helpers for clients, not strictly needed for verification.
    pub fn is_row(&self) -> bool {
        matches!(self, ExpandedVector::RowVector(_))
    }
    pub fn is_col(&self) -> bool {
        matches!(self, ExpandedVector::ColumnVector(_))
    }
}

/// Expands a 1-D vector into either a row or a column vector,
/// depending on the axis argument:
///   - axis == 0: row
///   - axis == 1: column
///
/// Requires:
///   * axis ≤ 1
///
/// Ensures:
///   * If the result is a RowVector(v), then axis == 0 and v == a
///   * If the result is a ColumnVector(v), then axis == 1 and v == a
#[requires(axis <= 1)]
#[ensures(match result {
    ExpandedVector::RowVector(v)    => axis == 0 && v == a,
    ExpandedVector::ColumnVector(v) => axis == 1 && v == a,
})]
pub fn expand_dims<T: PartialEq>(a: Vec<T>, axis: usize) -> ExpandedVector<T> {
    if axis == 0 {
        ExpandedVector::RowVector(a)
    } else {
        // Since we know axis ≤ 1 and axis ≠ 0, we can assert axis == 1
        assert!(axis == 1);
        ExpandedVector::ColumnVector(a)
    }
}

